contract InvMutTest
{
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(LogFile _log, uint256 a, uint256 b) public
    { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a) + (b)); require(a <= 1000000000000000000000000000000); require(b <= 1000000000000000000000000000000);
        require(address(this).balance >= a + b);
        c.SetLogFile(address(_log)); if (__ESBMC_reverted()) return;
        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Deposit{value: a}(); if (__ESBMC_reverted()) return;
        c.Deposit{value: b}(); if (__ESBMC_reverted()) return;
        assert(c.balances(address(this)) == a + b);
    }

    receive() external payable {}
    fallback() external payable {}
}
